uniform float speed : 0.0 .. 5.0 = 1.2;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform float sweep : 0.0 .. 2.0 = 0.6;
uniform float strobe : 0.0 .. 20.0 = 8.0;
uniform vec3 red : color = 1.0, 0.05, 0.02;
uniform vec3 blue : color = 0.05, 0.15, 1.0;
state fixed ph;
state fixed w;
state fixed sw;
state fixed sat;
void update() {
  ph = fract(ph + fixed(dt * speed * 0.5));
  w = fixed(width);
  sw = fixed(sweep);
  sat = fixed(0.85);
}
vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed beam = ang + ph;
  fixed lobe = sin(beam * fixed(2.0));
  fixed side = step(fixed(0.0), lobe);
  fixed d = abs(beam - fixed(0.5) * floor(beam + fixed(0.5)));
  fixed glow = clamp(fixed(1.0) - d * sw, fixed(0.0), fixed(1.0));
  fixed v = glow * (fixed(0.25) + fixed(0.75) * side) + fixed(0.02);
  fixed h = mix(fixed(0.0), fixed(0.6), side);
  return hsv2rgb(h, sat, clamp(v, fixed(0.0), fixed(1.0)));
}
